    t.ok(legal.includes(T.stackItem(b1).id), 'the Shock at my creature');
    t.ok(legal.includes(T.stackItem(b2).id), 'the Bolt at me');
    t.no(legal.includes(T.stackItem(b3).id), 'not the Bolt at its caster');
