    for (const n of ["Trespasser's Curse", "Curse of Fool's Wisdom", 'Grievous Wound', 'Curse of Exhaustion', 'Curse of Predation', 'Curse of the Forsaken', "Curse of Death's Hold"]) t.auto(n);
