    t.ok(ml && T.g.hasKw(ml, 'indestructible'));
    const T2 = mk();
    T2.bf('B', 'Aven Mindcensor');
    for (let i = 0; i < 6; i++) T2.top('A', 'Island');
    const deep = T2.g.zones.A.library.find(c => c.name === 'Plains');
