    const bear = T.bf('A', 'Grizzly Bears');
    T.mana('A', 'U');
    T.activate('A', lic, 0, { targets: [bear] });
    T.settle(); T.resolve();
    t.eq(lic.attachedTo, bear.id, 'attached to the Bears');
