    const la = tp.analysis(), idx = la.manaAbilities.length + la.abilities.filter(a => a.kind === 'activated').length - 1;
    t.ok(T.g.activateAbility('A', tp.id, idx, {}), T.g.lastError);
    T.settle(); T.resolve();
    t.eq(g1.zone, 'library'); t.eq(g2.zone, 'library');
    const T2 = mk();
