    ff.attachedTo = elves.id; elves.attachments = [ff.id]; ff.ts = U.g._stampNew();
    U.g.bumpBoard();
    t.ok(U.g._hasFlag(elves, 'cantActivateNonMana'), 'fettered');
    t.no(U.g._hasFlag(vamp, 'cantActivateNonMana'));
