    T.grave('A', 'Forest');
    T.answer('declareAttackers', () => [{ attackerId: bear.id, defenderId: 'B' }]);
    T.answer('pickTarget', { targets: [{ kind: 'object', id: bolt.id }] });
    T.toMain('A', 'endCombat');
