    t.zone(van, 'graveyard', 'Ragnarok dies: Vanille');
    t.zone(giant, 'graveyard', 'Ragnarok dies: Hill Giant destroyed');
    t.zone(bear, 'battlefield', 'Ragnarok dies: Grizzly Bears back');
