  test('Meld: a commander melded — the melded permanent is the commander, its damage counted, and the commander goes home alone', (mk, t) => {
    const M = mk({ library: Array(30).fill('Island') });
    const g = M.g;
    const gis = M.bf('A', 'Gisela, the Broken Blade');
    const bru = M.bf('A', 'Bruna, the Fading Light');
    // Bruna the commander: Gisela's trigger, but Bruna's object carries Brisela
    bru.isCommander = true;
    g.config.commanderDamage = 21;
    g.player('B').commanderDamage[bru.id] = 0;
    g.player('A').commanderCasts[bru.id] = 1;
    M.toMain('A', 'end');
    M.resolve();
    t.zone(bru, 'battlefield', 'the commander carries the melded permanent');
    t.eq(bru.name, 'Brisela, Voice of Nightmares');
    t.ok(bru.isCommander);
    t.zone(gis, 'merged');
    M.nextTurn('A');
    M.answer('declareAttackers', () => [{ attackerId: bru.id, defenderId: 'B' }]);
    M.toMain('A', 'endCombat');
    t.eq(g.player('B').commanderDamage[bru.id], 9, 'Brisela: 9 commander damage');
    M.nextTurn('A');
    M.mana('A', '1BB');
    M.cast('A', M.hand('A', 'Murder'), { targets: [bru.id] });
    t.zone(bru, 'command', 'Brisela dies: Bruna to the command zone');
    t.zone(gis, 'graveyard', 'Brisela dies: Gisela to the graveyard');
    t.eq(bru.name, 'Bruna, the Fading Light');
    t.eq(g._commanderTax(bru).mana, 2, 'the tax carries on');
  });

  test('Meld: a melded permanent survives a save and an undo, and goes onto the library as two cards its owner orders', (mk, t) => {
    const M = mk({ library: Array(30).fill('Island') });
    const g = M.g;
    const gis = M.bf('A', 'Gisela, the Broken Blade');
    const bru = M.bf('A', 'Bruna, the Fading Light');
    M.toMain('A', 'end');
    M.resolve();
    const hostId = [gis, bru].find(o => o.zone === 'battlefield').id;
    // through JSON and back: the game a save resumes
    g.restore(JSON.parse(JSON.stringify(g.snapshot())));
    const host = g.obj(hostId);
    t.eq(host.name, 'Brisela, Voice of Nightmares', 'restored: still Brisela');
    t.eq(host.analysis().mv, 11);
    const other = g.obj(host.meld.partner);
    t.zone(other, 'merged', 'restored: the other card still inside it');
    t.ok(g.viewFor('A').battlefield.find(v => v.id === hostId).melded.length === 2, 'restored: the view has both names');
    // on top of the library: both cards, in the order A says
    M.nextTurn('A');
    M.answer('choose', (ch) => ({ picks: [other.id] }));
    M.mana('A', '3U');
    M.cast('A', M.hand('A', 'Griptide'), { targets: [hostId] });
    const lib = g.zones.A.library;
    t.zone(host, 'library', 'Griptide: Gisela/Bruna to the library');
    t.zone(other, 'library');
    t.ok(M.asked.some(ch => ch.purpose === 'meldOrder'), 'A is asked which goes on top');
    t.eq(lib[0], other, 'the one A picked is on top');
    t.eq(lib[1], host);
  });

  test('Meld: a bot pays for Hanweir Battlements only with the Garrison there', (mk, t) => {
    const M = mk({ library: Array(30).fill('Mountain') });
    const g = M.g;
    const B = M.MTG.bots;
    const bat = M.bf('A', 'Hanweir Battlements');
    for (let i = 0; i < 5; i++) M.bf('A', 'Mountain');
    const bot = new B.BotPlayer(g, 'A', 8);
    const a = bat.analysis();
    const all = a.manaAbilities.concat(a.abilities.filter(x => x.kind === 'activated' || x.kind === 'loyalty'));
    const meldIx = all.findIndex(x => (x.effects || []).some(e => e.op === 'meld'));
    t.eq(meldIx, 2);
    t.no(bot._abilityCandidate(bat, a, all[meldIx], meldIx, 'main1', bot.manaSources()), 'bot: no Garrison, no meld');
    M.bf('A', 'Hanweir Garrison');
    t.ok(bot._abilityCandidate(bat, a, all[meldIx], meldIx, 'main1', bot.manaSources()), 'bot: with the Garrison, worth it');
  });

  test('Commanders: Fandaniel, Telophoroi Ascian — surveil on instants; each opponent sacrifices a nontoken creature or loses 2 a spell card', (mk, t) => {
    t.auto('Fandaniel, Telophoroi Ascian');
    const M = mk({ players: ['A', 'B', 'C'], library: Array(30).fill('Island') });
    M.bf('A', 'Fandaniel, Telophoroi Ascian');
    // "Whenever you cast an instant or sorcery spell, surveil 1."
    const a0 = M.asked.length;
    M.mana('A', 'R');
    M.cast('A', M.hand('A', 'Lightning Bolt'), { targets: ['C'] });
    t.ok(M.asked.slice(a0).some(ch => ch.type === 'surveil'), 'Fandaniel: surveil 1');
    M.grave('A', 'Opt');
    M.grave('A', 'Grizzly Bears');
    // two instants in A's graveyard: 4 life. B sacrifices its Bears; C has only a token, so loses
    const bears = M.bf('B', 'Grizzly Bears');
    M.g._createToken('C', { n: 1, pt: '1/1', subtypes: 'Soldier', colorWords: ['white'], keywords: [] });
    const lifeC = M.life('C');
    M.answer('choose', () => ({ picks: [bears.id] }));
    M.toMain('A', 'end'); M.resolve();
    t.zone(bears, 'graveyard', 'Fandaniel: B sacrificed');
    t.eq(M.life('B'), 20, 'Fandaniel: B who sacrificed loses nothing');
    t.eq(M.life('C'), lifeC - 4, 'Fandaniel: C, with only a token, loses 2 for each of 2 instants');
    t.eq(M.asked.filter(ch => ch.purpose === 'unlessSacrifice' && ch.playerId === 'C').length, 0, 'Fandaniel: C has nothing to choose from');
    // next end step: B declines with a creature in play
    const bears2 = M.bf('B', 'Grizzly Bears');
    M.nextTurn('A');
    M.answer('choose', () => ({ picks: [] }));
    M.toMain('A', 'end'); M.resolve();
    t.zone(bears2, 'battlefield', 'Fandaniel: B declines');
    t.eq(M.life('B'), 16, 'Fandaniel: and loses 4');
  });

  test('Commanders: Clavileño, First of the Blessed — an attacking Vampire becomes a Demon that draws and makes a 4/3 when it dies', (mk, t) => {
    t.auto('Clavileño, First of the Blessed');
    const M = mk({ library: Array(30).fill('Island') });
    const clav = M.bf('A', 'Clavileño, First of the Blessed');
    const vamp = M.bf('A', 'Vampire Interloper');
    const bears = M.bf('A', 'Grizzly Bears');
    let opts = null;
    M.answer('pickTarget', (ch) => { opts = ch.options; return { targets: [vamp.id] }; });
    M.answer('declareAttackers', () => [clav, vamp, bears].map(o => ({ attackerId: o.id, defenderId: 'B' })));
    M.toMain('A', 'declareBlockers');
    const ids = (opts || []).flat().map(x => (x && x.id) || x);
    t.ok(ids.includes(clav.id) && ids.includes(vamp.id), 'Clavileño: the attacking Vampires');
    t.no(ids.includes(bears.id), 'Clavileño: not a Bear');
    t.ok(M.g._hasSubtype(vamp, 'Demon'), 'Clavileño: the Interloper is a Demon');
    t.ok(M.g._hasSubtype(vamp, 'Vampire'), 'Clavileño: in addition to its other types');
    // it dies: a card and a tapped 4/3 flier
    M.toMain('A', 'main');
    M.nextTurn('A');
    t.ok(M.g._hasSubtype(vamp, 'Demon'), 'Clavileño: a Demon for good');
    const hand0 = M.zone('A', 'hand').length;
    M.mana('A', 'R');
    M.cast('A', M.hand('A', 'Lightning Bolt'), { targets: [vamp.id] });
    t.zone(vamp, 'graveyard');
    t.eq(M.zone('A', 'hand').length, hand0 + 1, 'Clavileño: drew a card');
    const tok = M.bfOf('A').find(o => o.isToken);
    t.ok(tok && tok.tapped, 'Clavileño: a tapped token');
    const ch = tok && M.g.characteristics(tok);
    t.eq(ch && M.g.powerOf(tok) + '/' + M.g.toughnessOf(tok), '4/3', 'Clavileño: a 4/3');
    t.ok(tok && M.g._hasSubtype(tok, 'Vampire') && M.g._hasSubtype(tok, 'Demon'), 'Clavileño: a Vampire Demon');
    // next combat: the Demon token attacking too can't be picked; Clavileño itself can
    opts = null;
    M.nextTurn('A');
    M.answer('pickTarget', (c) => { opts = c.options; return { targets: [clav.id] }; });
    M.answer('declareAttackers', () => [clav, tok].map(o => ({ attackerId: o.id, defenderId: 'B' })));
    M.toMain('A', 'declareBlockers');
    const ids2 = (opts || []).flat().map(x => (x && x.id) || x);
    t.no(ids2.includes(tok.id), "Clavileño: a Vampire that's a Demon already is not a target");
    t.ok(M.g._hasSubtype(clav, 'Demon'), 'Clavileño: itself a Demon now');
  });

  test('Commanders: Calix, Guided by Fate — Calix or an enchanted creature hitting a player: a copy of a nonlegendary enchantment, once a turn', (mk, t) => {
    t.auto('Calix, Guided by Fate');
    let M = mk({ library: Array(30).fill('Island') });
    const calix = M.bf('A', 'Calix, Guided by Fate');
    const bears = M.bf('A', 'Grizzly Bears');
    const elves = M.bf('A', 'Llanowar Elves');
    const anthem = M.bf('A', 'Glorious Anthem');
    M.mana('A', 'W');
    M.cast('A', M.hand('A', 'Holy Strength'), { targets: [bears.id] });
    // Constellation: the Aura entering put a +1/+1 counter on a creature
    t.eq([calix, bears, elves].reduce((s, o) => s + (o.counters['+1/+1'] || 0), 0), 1, 'Calix: constellation, one counter');
    const picks = [];
    M.answer('choose', (ch) => { picks.push(ch); return { picks: [anthem.id] }; });
    M.answer('declareAttackers', () => [calix, bears, elves].map(o => ({ attackerId: o.id, defenderId: 'B' })));
    M.toMain('A', 'endCombat');
    const copies = () => M.bfOf('A').filter(o => o.isToken && o.name === 'Glorious Anthem');
    t.eq(copies().length, 1, 'Calix: one Anthem copy, only once each turn');
    t.eq(M.asked.filter(ch => ch.purpose === 'effectObject').length, 1, 'Calix: asked once');
    t.no(M.asked.some(ch => ch.type === 'confirm'), 'Calix: the pick is the "may", no yes/no first');
    // a fresh table: the first pick declined leaves it for the second trigger
    M = mk({ library: Array(30).fill('Island') });
    const c2 = M.bf('A', 'Calix, Guided by Fate');
    const b2 = M.bf('A', 'Grizzly Bears');
    const an2 = M.bf('A', 'Glorious Anthem');
    M.mana('A', 'W');
    M.cast('A', M.hand('A', 'Holy Strength'), { targets: [b2.id] });
    let n = 0;
    const offered = [];
    M.answer('choose', (ch) => { offered.push(ch.items.map(it => it.id)); n++; return { picks: n === 1 ? [] : [an2.id] }; });
    M.answer('choose', (ch) => { offered.push(ch.items.map(it => it.id)); n++; return { picks: n === 1 ? [] : [an2.id] }; });
    M.answer('declareAttackers', () => [c2, b2].map(o => ({ attackerId: o.id, defenderId: 'B' })));
    M.toMain('A', 'endCombat');
    t.eq(n, 2, 'Calix: declined, then asked again');
    t.eq(M.bfOf('A').filter(o => o.isToken && o.name === 'Glorious Anthem').length, 1, 'Calix: the second trigger makes the copy');
    t.ok(offered[0].includes(an2.id), 'Calix: the Anthem offered');
    const hs = M.bfOf('A').find(o => o.name === 'Holy Strength');
    t.ok(offered[0].includes(hs.id), 'Calix: an Aura is a nonlegendary enchantment too');
    t.no(offered[0].includes(c2.id), 'Calix: not itself, legendary');
    // no nonlegendary enchantment: nothing asked
    M = mk({ library: Array(30).fill('Island') });
    const c3 = M.bf('A', 'Calix, Guided by Fate');
    const a3 = M.asked.length;
    M.answer('declareAttackers', () => [{ attackerId: c3.id, defenderId: 'B' }]);
    M.toMain('A', 'endCombat');
    t.eq(M.life('B'), 18, 'Calix: hit');
    t.no(M.asked.slice(a3).some(ch => ch.purpose === 'effectObject' || ch.type === 'confirm'), 'Calix: nothing to copy, nothing asked');
  });

  test("Commanders: Tidus, Yuna's Guardian — a counter moved at the beginning of combat; Cheer draws and proliferates once a turn", (mk, t) => {
    t.auto("Tidus, Yuna's Guardian");
    const M = mk({ players: ['A', 'B', 'C'], library: Array(30).fill('Island') });
    M.bf('A', "Tidus, Yuna's Guardian");
    const bears = M.bf('A', 'Grizzly Bears', { counters: { '+1/+1': 1, shield: 1 } });
    const elves = M.bf('A', 'Llanowar Elves');
    const ogre = M.bf('A', 'Gray Ogre');
    let opts = null;
    M.answer('pickTarget', (ch) => { opts = ch.options; return { targets: [bears.id, elves.id] }; });
    // two kinds on the Bears: the +1/+1 one is picked
    M.answer('choose', (ch) => ({ picks: [ch.options.findIndex(o => o.label === '+1/+1')] }));
    M.answer('declareAttackers', () => [{ attackerId: elves.id, defenderId: 'B' }, { attackerId: bears.id, defenderId: 'C' }, { attackerId: ogre.id, defenderId: 'B' }]);
    M.toMain('A', 'endCombat');
    t.ok(opts && opts[0].every(o => o.kind === 'object' && M.g.obj(o.id).controller === 'A'), 'Tidus: creatures A controls');
    t.eq(M.asked.filter(ch => ch.purpose === 'counterKind').length, 1, 'Tidus: asked which counter');
    // moved: the Bears keep the shield; the Elves get the +1/+1, then proliferate adds one to each
    t.eq(bears.counters['+1/+1'] || 0, 0, 'Tidus: the +1/+1 counter left the Bears');
    t.eq(elves.counters['+1/+1'], 2, 'Tidus: moved to the Elves, and proliferated');
    t.eq(bears.counters.shield, 2, 'Tidus: the shield counter proliferated');
    t.eq(M.zone('A', 'hand').length, 1, 'Tidus: Cheer drew one card, though two players were hit');
    t.eq(ogre.counters['+1/+1'] || 0, 0, 'Tidus: the Ogre has none');
    // declined: nothing moves
    M.nextTurn('A');
    M.answer('confirm', () => ({ yes: false }));
    M.toMain('A', 'end');
    M.settle();
    t.eq(elves.counters['+1/+1'], 2, 'Tidus: declined, nothing moved');
    // only the Ogre, with no counters, connects: no Cheer
    const hand = M.zone('A', 'hand').length;
    M.nextTurn('A');
    M.answer('confirm', () => ({ yes: false }));
    M.answer('declareAttackers', () => [{ attackerId: ogre.id, defenderId: 'B' }]);
    M.toMain('A', 'endCombat');
    t.eq(M.zone('A', 'hand').length, hand + 1, 'Tidus: a creature without counters is no cheer (only the turn draw)');
  });

