    M.mana('A', '2RW');
    M.cast('A', M.hand('A', 'Éowyn, Fearless Knight'));
    const eow = M.bfOf('A').find(o => o.name === 'Éowyn, Fearless Knight');
    t.ok(eow, 'Éowyn: on the battlefield');
