    const bear = T.bf('A', 'Grizzly Bears');
    const angel = T.bf('B', 'Serra Angel');
    T.answer('pickTarget', { targets: [bear.id, angel.id] });
    const ex = T.put('A', 'Exchange of Words', 'battlefield', { etb: true });
    T.resolve();
