  test("Commanders: Captain N'ghathrod — mill on combat damage, then at the end step take an artifact or creature milled this turn", (mk, t) => {
    t.auto("Captain N'ghathrod");
    const M = mk({ library: Array(30).fill('Island') });
    const g = M.g;
    const cap = M.bf('A', "Captain N'ghathrod");
    t.ok(g.hasKw(cap, 'menace'), "N'ghathrod: Horrors you control have menace");
    const old = M.grave('B', 'Hill Giant');
    const bolt = M.top('B', 'Lightning Bolt'), stone = M.top('B', 'Mind Stone'), bear = M.top('B', 'Grizzly Bears');
    M.answer('declareAttackers', () => [{ attackerId: cap.id, defenderId: 'B' }]);
    toMain2(M);
    t.eq(M.life('B'), 17);
    [bear, stone, bolt].forEach(o => t.zone(o, 'graveyard', "N'ghathrod: B mills three"));
    let asked = null;
    M.answer('pickTarget', (ch) => { asked = ch; return { targets: [{ kind: 'object', id: bear.id }] }; });
    M.toMain('A', 'end'); M.resolve();
    const offered = asked ? asked.options[0].map(x => x.id) : [];
    t.ok(offered.includes(bear.id) && offered.includes(stone.id), "N'ghathrod: the creature and the artifact milled this turn");
    t.no(offered.includes(bolt.id), "N'ghathrod: not an instant");
    t.no(offered.includes(old.id), "N'ghathrod: not one put there some other way");
    t.zone(bear, 'battlefield');
    t.eq(bear.controller, 'A', "N'ghathrod: under your control");
  });
