    g._createNamedToken('A', { token: 'Treasure', n: 1 });
    trs.push(M.bfOf('A').filter(o => o.name === 'Treasure').pop());
    for (const tr of trs) t.ok(g.tapForMana('A', tr.id, 0, 'R'), 'Kalain: a Treasure for {R}');
    t.eq(trs.filter(tr => tr.zone === 'battlefield').length, 0, 'Kalain: both sacrificed');
