  test('Commanders: Gilgamesh, Master-at-Arms — enters: Equipment from the top six onto the battlefield, one attached to a Samurai', (mk, t) => {
    t.auto('Gilgamesh, Master-at-Arms');
    const M = mk({ library: Array(30).fill('Island') });
    const bear = M.bf('A', 'Grizzly Bears');
    const names = ['Bonesplitter', 'Grizzly Bears', 'Short Sword', 'Forest', 'Lightning Bolt', 'Mountain'];
    const cards = names.slice().reverse().map(n => M.top('A', n)).reverse();
    const [bs, gb, ss] = cards;
    let offered = null, asked = null;
    M.answer('pickCard', (ch) => { offered = ch; return { cardIds: [bs.id, ss.id] }; });
    M.answer('choose', (ch) => { asked = ch; return { picks: [bs.id] }; });
    const gil = M.bf('A', 'Gilgamesh, Master-at-Arms', { etb: true }); M.resolve();
    const ids = offered ? offered.cards.map(c => c.id) : [];
    t.ok(ids.includes(bs.id) && ids.includes(ss.id) && ids.length === 2, 'Gilgamesh: only the Equipment offered');
    t.zone(bs, 'battlefield'); t.zone(ss, 'battlefield');
    t.ok(asked && asked.optional && asked.items.length === 2, 'Gilgamesh: you may attach one of them');
    t.eq(bs.attachedTo, gil.id, 'Gilgamesh: Bonesplitter on the Samurai');
    t.no(ss.attachedTo, 'Gilgamesh: only one of them');
    t.no((bear.attachments || []).length, 'Gilgamesh: not on a creature that is not a Samurai');
    const lib = M.zone('A', 'library');
    t.ok(lib.indexOf(gb) >= lib.length - 4, 'Gilgamesh: the rest on the bottom');
  });
