    const s3 = M.bf('A', 'History of Benalia', { counters: { lore: 1 } });
    const theirs = M.bf('B', 'The Eldest Reborn', { counters: { lore: 1 } });
    M.answer('declareAttackers', () => [{ attackerId: gar.id, defenderId: 'B' }]);
