    M.nextTurn('A');
    M.answer('declareAttackers', () => [{ attackerId: gar.id, defenderId: 'B' }]);
    M.answer('choose', () => ({ picks: [] }));
    M.toMain('A', 'endCombat');
    t.eq(gar.counters['+1/+1'], 2, 'none removed, none put');
