  test('Commanders: Fblthp, Lost on the Range — the top card of your library plotted for its mana cost, cast free on a later turn', (mk, t) => {
    t.auto('Fblthp, Lost on the Range');
    const M = mk({ library: Array(30).fill('Island') });
    const g = M.g;
    M.bf('A', 'Fblthp, Lost on the Range');
    const bear = M.top('A', 'Grizzly Bears');
    const v = g.viewFor('A');
    t.ok(v.players.find(p => p.id === 'A').topCard, 'Fblthp: you may look at the top card');
    const uses = (v.uses || {})[bear.id] || [];
    t.eq(uses.map(u => u.kind + ' ' + u.cost).join(), 'plot {1}{G}', 'Fblthp: plot for its mana cost');
    t.no(g.plotCard('A', bear.id, { auto: true }), 'Fblthp: no mana, no plot');
    M.mana('A', 'G1');
    t.ok(g.playableNow('A').some(x => x.kind === 'plot' && x.objId === bear.id), 'Fblthp: offered');
    t.ok(g.plotCard('A', bear.id, { auto: true }), 'Fblthp: plotted');
    t.zone(bear, 'exile');
    t.ok(!(g.viewFor('A').uses || {})[bear.id], 'Fblthp: nothing more from the top');
    t.no(g.castSpell('A', bear.id, { auto: true }), 'Fblthp: not this turn');
    M.nextTurn('A');
    t.ok(g.castSpell('A', bear.id, { auto: true, via: 'plot' }), 'Fblthp: a later turn, for nothing');
    M.resolve();
    t.zone(bear, 'battlefield');
  });
  test('Commanders: Fblthp, Lost on the Range — not a land, not at instant speed, not without Fblthp; a card with plot of its own', (mk, t) => {
    const M = mk({ library: Array(30).fill('Island') });
    const g = M.g;
    const fb = M.bf('A', 'Fblthp, Lost on the Range');
    const land = M.top('A', 'Forest');
    t.ok(!((g.viewFor('A').uses || {})[land.id]), 'Fblthp: a land cannot be plotted');
    g.moveObject(land, 'graveyard');
    const bolt = M.top('A', 'Lightning Bolt');
    M.mana('A', 'R');
    M.toMain('B');
    t.no(g.plotCard('A', bolt.id, { auto: true }), "Fblthp: only when you could cast a sorcery");
    g.moveObject(bolt, 'graveyard');
    M.nextTurn('A');
    // a card with plot of its own: its own plot cost or its mana cost, the cheaper paid
    const bo = M.top('A', 'Beastbond Outcaster');
    const costs = ((g.viewFor('A').uses || {})[bo.id] || []).map(u => u.cost).sort();
    t.eq(costs.join(' '), '{1}{G} {2}{G}', 'Fblthp: both costs offered');
    M.mana('A', 'GG1');
    t.ok(g.plotCard('A', bo.id, { auto: true }), 'Fblthp: plotted');
    t.ok(g.canPayNow('A', '{G}') && !g.canPayNow('A', '{G}{G}'), 'Fblthp: its own {1}{G} paid, {G} left');
    const kav = M.top('A', 'Grizzly Bears');
    g.moveObject(fb, 'graveyard');
    t.ok(!((g.viewFor('A').uses || {})[kav.id]), 'Fblthp: gone, no plot from the top');
  });
  test("Commanders: Betor, Ancestor's Voice — at your end step: counters for the life gained, a creature card back for the life lost", (mk, t) => {
    t.auto("Betor, Ancestor's Voice");
    const M = mk({ library: Array(30).fill('Island') });
    const g = M.g;
    const bet = M.bf('A', "Betor, Ancestor's Voice");
    const bear = M.bf('A', 'Grizzly Bears');
    const giant = M.grave('A', 'Hill Giant'), elves = M.grave('A', 'Llanowar Elves');
    const seen = [];
    M.answer('pickTarget', (ch) => {
      seen.push(ch);
      return { targets: (ch.options || []).map(l => l.find(x => x.id === bear.id || x.id === giant.id) || l[0]).filter(Boolean) };
    });
    g.changeLife('A', 3); g.changeLife('A', -2);
    M.toMain('A', 'end'); M.resolve();
    t.eq(bear.counters['+1/+1'] || 0, 3, 'Betor: three counters for 3 life gained');
    t.eq(bet.counters['+1/+1'] || 0, 0, 'Betor: not on itself');
    const opts = [].concat(...seen.map(ch => [].concat(...ch.options)));
    t.ok(!opts.some(x => x.id === giant.id), 'Betor: Hill Giant has mana value 4, more than 2');
    t.ok(opts.some(x => x.id === bear.id) && !opts.some(x => x.id === bet.id), 'Betor: another creature');
    t.zone(giant, 'graveyard');
    t.zone(elves, 'battlefield', 'Betor: Llanowar Elves comes back');
  });
