    t.zone(cos, 'exile', 'Cosima: in exile, no new upkeep trigger');
    say(true);
    M.playLand('A', M.hand('A', 'Forest'));
    t.eq(cos.counters.voyage, 2);
    const h0 = M.zone('A', 'hand').length;
