    t.eq(asked.max, 2, 'Ureni: no more targets than the damage allows');
    t.zone(giant, 'graveyard', 'Ureni: 3 to the Hill Giant');
    t.zone(bear, 'graveyard', 'Ureni: 2 to the Bears');
