  test('Commanders: Éomer, Marshal of Rohan — attacking legendaries die together: one trigger, everything untapped, another combat', (mk, t) => {
    t.auto('Éomer, Marshal of Rohan');
    const M = mk({ library: Array(10).fill('Mountain') });
    const g = M.g;
    M.toMain('A');
    const eo = M.bf('A', 'Éomer, Marshal of Rohan');
    const l1 = M.bf('A', 'Isamaru, Hound of Konda'), l2 = M.bf('A', 'Gaddock Teeg');
    const bear = M.bf('A', 'Grizzly Bears');
    for (const o of [eo, l1, l2, bear]) o.summoningSick = false;
    M.answer('declareAttackers', () => [eo, l1, l2, bear].map(o => ({ attackerId: o.id, defenderId: 'B' })));
    M.toMain('A', 'declareBlockers');
    t.ok(bear.tapped && eo.tapped, 'attacked, tapped');
    const before = (g._extraPhases || []).length;
    g.moveObject(bear, 'graveyard'); M.resolve();
    t.eq((g._extraPhases || []).length, before, 'Éomer: a nonlegendary attacker died — nothing');
    t.ok(eo.tapped, 'Éomer: still tapped');
    g.moveObject(l1, 'graveyard'); g.moveObject(l2, 'graveyard'); M.resolve();
    t.eq((g._extraPhases || []).length, before + 1, 'Éomer: one more combat phase');
    t.ok(!eo.tapped, 'Éomer: creatures untapped');
    const l3 = M.bf('A', 'Isamaru, Hound of Konda'); l3.attacking = true;
    g.moveObject(l3, 'graveyard'); M.resolve();
    t.eq((g._extraPhases || []).length, before + 1, 'Éomer: only once each turn');
  });
