  test('Commanders: The Reaper, King No More — enters: -1/-1 counters on up to two; an opponent\'s creature with one dies: yours, once a turn', (mk, t) => {
    t.auto('The Reaper, King No More');
    const M = mk({ library: Array(10).fill('Swamp') });
    const g = M.g;
    M.toMain('A');
    const b1 = M.bf('B', 'Grizzly Bears'), b2 = M.bf('B', 'Hill Giant'), b3 = M.bf('B', 'Hill Giant'), plain = M.bf('B', 'Hill Giant');
    M.answer('pickTarget', (ch) => ({ targets: [b1.id, b2.id].map((id, i) => ((ch.options || [])[i] || []).find(x => x.id === id)).filter(Boolean) }));
    M.mana('A', 'BRG3');
    M.cast('A', M.hand('A', 'The Reaper, King No More'));
    t.eq((b1.counters || {})['-1/-1'], 1, 'Reaper: a counter on the Bears');
    t.eq((b2.counters || {})['-1/-1'], 1, 'Reaper: a counter on a Hill Giant');
    let asked = 0;
    M.answer('confirm', () => { asked++; return { yes: true }; });
    g.moveObject(plain, 'graveyard'); M.resolve();
    t.eq(asked, 0, 'Reaper: no -1/-1 counter — nothing');
    t.zone(plain, 'graveyard');
    g.moveObject(b2, 'graveyard'); M.resolve();
    t.zone(b2, 'battlefield', 'Reaper: the Hill Giant comes back');
    t.eq(b2.controller, 'A', 'Reaper: under your control');
    g.addCounters(b3, '-1/-1', 1);
    g.moveObject(b3, 'graveyard'); M.resolve();
    t.zone(b3, 'graveyard', 'Reaper: only once each turn');
    M.nextTurn('B'); M.nextTurn('A');
    g.moveObject(b1, 'graveyard'); M.resolve();
    t.zone(b1, 'battlefield', 'Reaper: a new turn, again');
    t.eq(b1.controller, 'A');
    const mine = M.bf('A', 'Grizzly Bears'); g.addCounters(mine, '-1/-1', 1);
    M.nextTurn('B');
    g.moveObject(mine, 'graveyard'); M.resolve();
    t.zone(mine, 'graveyard', 'Reaper: your own creature does not count');
  });
