    M.answer('pickTarget', (ch) => { picked = ch.options.map(l => l[0] && l[0].id); return { targets: [{ kind: 'object', id: bearB.id }] }; });
    M.answer('declareAttackers', () => [{ attackerId: gor.id, defenderId: 'B' }, { attackerId: bear.id, defenderId: 'C' }]);
    M.toMain('A', 'declareBlockers');
    t.ok(picked && !picked.includes(giantC.id), "Gornog: only a creature of the player the Warriors attack");
    t.ok(g._hasCreatureType(bearB, 'Coward'), 'Gornog: becomes a Coward');
    t.no(g._hasCreatureType(bearB, 'Bear'), 'Gornog: and nothing else');
    t.no(g._hasCreatureType(giantC, 'Coward'), 'Gornog: a Bear attacking C, no trigger for C');
    t.eq(g.powerOf(gor), 3, 'Gornog: attacking Warriors +1/+0 for the one Coward');
    t.eq(g.toughnessOf(gor), 3, 'Gornog: +0 toughness');
    t.eq(g.powerOf(bear), 2, 'Gornog: not a Warrior');
    t.no(g.canBlock(bearB, gor), "Gornog: Cowards can't block Warriors");
    t.ok(g.canBlock(giantC, bear), 'Gornog: other blocks as usual');
    M.toMain('A', 'end');
