  test('Commanders: Mr. House, President and CEO — a die, and one more for each Treasure mana spent; 4+ a Robot, 6+ a Treasure too', (mk, t) => {
    t.auto('Mr. House, President and CEO');
    const M = mk({ library: Array(30).fill('Island') });
    const g = M.g;
    const house = M.bf('A', 'Mr. House, President and CEO');
    const robots = () => M.bfOf('A').filter(o => o.isToken && /Robot/.test(o.name)).length;
    const treasures = () => M.bfOf('A').filter(o => o.isToken && /Treasure/.test(o.name)).length;
    let rolls = [3];
    g.rng.range = () => rolls.shift() || 1;
    M.mana('A', '4');
    M.activate('A', house, 0);
    t.eq(robots(), 0, 'Mr. House: a 3, nothing');
    house.tapped = false;
    rolls = [4];
    M.mana('A', '4');
    M.activate('A', house, 0);
    t.eq(robots(), 1, 'Mr. House: a 4, a Robot');
    t.eq(treasures(), 0, 'Mr. House: no Treasure under 6');
    // two Treasures sacrificed for mana: three dice
    house.tapped = false;
    g._createNamedToken('A', { token: 'Treasure', n: 2 });
    const [tr1, tr2] = M.bfOf('A').filter(o => o.isToken && /Treasure/.test(o.name));
    for (const tr of [tr1, tr2]) t.ok(g.tapForMana('A', tr.id, 0, 'R'), g.lastError);
    M.mana('A', '2');
    rolls = [6, 2, 5];
    M.activate('A', house, 0);
    t.zone(tr1, 'graveyard');
    t.eq(robots(), 3, 'Mr. House: three dice, a 6 and a 5 make two Robots');
    t.eq(treasures(), 1, 'Mr. House: the 6 a Treasure as well');
  });
