  test('Commanders: Calamity, Galloping Inferno — attacks saddled: two tapped and attacking copies of what saddled it, sacrificed at the end step', (mk, t) => {
    t.auto('Calamity, Galloping Inferno');
    const M = mk({ library: Array(30).fill('Mountain') });
    const g = M.g;
    M.toMain('A');
    const cal = M.bf('A', 'Calamity, Galloping Inferno'); cal.summoningSick = false;
    const bear = M.bf('A', 'Grizzly Bears'), giant = M.bf('A', 'Hill Giant');
    const legend = M.bf('A', 'Isamaru, Hound of Konda');
    M.activate('A', cal, 0, { tapped: [bear, giant, legend].map(o => ({ kind: 'object', id: o.id })) });
    t.ok(bear.tapped && giant.tapped && legend.tapped, 'Calamity: saddled by three');
    const offered = [];
    M.answer('choose', (ch) => { offered.push(ch.items.map(x => x.id)); return { picks: [bear.id] }; });
    M.answer('choose', (ch) => { offered.push(ch.items.map(x => x.id)); return { picks: [giant.id] }; });
    M.answer('declareAttackers', () => [{ attackerId: cal.id, defenderId: 'B' }]);
    M.toMain('A', 'declareBlockers');
    t.eq(offered.length, 2, 'Calamity: chosen twice');
    t.ok(offered.every(l => l.length === 2 && !l.includes(legend.id)), 'Calamity: not the legendary Isamaru');
    const toks = g.battlefield.filter(o => o.isToken && o.controller === 'A');
    t.eq(M.names(toks).sort().join(), 'Grizzly Bears,Hill Giant', 'Calamity: a Bears and a Giant');
    t.ok(toks.every(o => o.tapped && o.attacking === 'B'), 'Calamity: tapped and attacking');
    M.toMain('A', 'end');
    t.eq(M.life('B'), 20 - g.powerOf(cal) - 2 - 3, 'Calamity: the copies dealt their damage');
    M.nextTurn('B');
    t.ok(toks.every(o => o.zone !== 'battlefield'), 'Calamity: sacrificed at the end step');
    t.zone(bear, 'battlefield'); t.zone(giant, 'battlefield');
  });
