    t.eq(kim.name, 'Kimahri, Valiant Guardian', 'Kimahri: the name kept');
    t.eq(g.powerOf(kim), 5, 'Kimahri: a 4/4 Angel with a counter');
    const kw = ['Flying', 'Vigilance'].filter(k => g.hasKw(kim, k));
    t.ok(kw.includes('Flying') && kw.includes('Vigilance'), "Kimahri: the Angel's flying, and vigilance");
