  test("Commanders: Xanathar, Guild Kingpin — your upkeep: the opponent can't cast spells; you see and play the top card of their library with mana of any color", (mk, t) => {
    t.auto('Xanathar, Guild Kingpin');
    const M = mk({ library: Array(30).fill('Island'), players: ['A', 'B', 'C'] });
    const g = M.g;
    M.toMain('A');
    M.bf('A', 'Xanathar, Guild Kingpin');
    M.nextTurn('B'); M.nextTurn('C');
    M.answer('pickTarget', (ch) => ({ targets: [((ch.options || [])[0] || []).find(x => x.id === 'B')].filter(Boolean) }));
    M.nextTurn('A');
    M.toMain('A');
    const giant = M.top('B', 'Hill Giant');
    const pB = g.viewFor('A').players.find(p => p.id === 'B');
    t.ok(pB.topCard && pB.topCard.id === giant.id, "Xanathar: B's top card shown to you");
    t.no(g.viewFor('C').players.find(p => p.id === 'B').topCard, 'Xanathar: not to C');
    t.no((g.viewFor('A').players.find(p => p.id === 'C') || {}).topCard, "Xanathar: not C's top card");
    M.mana('A', '4');
    t.ok(g.playableNow('A').some(x => x.objId === giant.id), 'Xanathar: the Giant is yours to cast');
    M.cast('A', giant);
    t.zone(giant, 'battlefield', 'Xanathar: {3}{R} paid with four colorless — mana as though it were any color');
    t.eq(giant.controller, 'A', 'Xanathar: under your control');
    const mtn = M.top('B', 'Mountain');
    t.ok(g.playLand('A', mtn.id), 'Xanathar: a land from the top of their library, as your land play');
    t.eq(mtn.controller, 'A');
    const bolt = M.hand('B', 'Lightning Bolt');
    M.mana('B', 'R');
    t.no(g.canCast('B', bolt.id).ok && g.castSpell('B', bolt.id, { targets: [{ kind: 'player', id: 'A' }] }), "Xanathar: B can't cast spells");
    const ctop = M.top('C', 'Grizzly Bears');
    t.no(g.playableNow('A').some(x => x.objId === ctop.id), "Xanathar: C's library isn't yours to play");
    M.nextTurn('B');
    const top2 = M.top('B', 'Grizzly Bears');
    t.no(g.playableNow('A').some(x => x.objId === top2.id), 'Xanathar: until end of turn');
    t.no((g.viewFor('A').players.find(p => p.id === 'B') || {}).topCard, 'Xanathar: and no longer shown');
  });
