  test('Commanders: Rendmaw, Creaking Nest — the goad outlasts the goader\'s next turn', (mk, t) => {
    const M = mk({ library: Array(30).fill('Island'), players: ['A', 'B', 'C'] });
    const g = M.g;
    M.mana('A', 'BG3');
    M.cast('A', M.hand('A', 'Rendmaw, Creaking Nest'));
    const bird = g.battlefield.find(o => o.isToken && o.controller === 'B');
    // each goaded Bird attacks a player other than A
    const decl = (ch) => g.battlefield.filter(o => o.controller === ch.playerId && g.canAttack(o) && g.mustAttack(o))
      .map(o => ({ attackerId: o.id, defenderId: ch.playerId === 'C' ? 'B' : 'C' }));
    for (let i = 0; i < 4; i++) M.answer('declareAttackers', decl);
    M.nextTurn('B'); M.nextTurn('C'); M.nextTurn('A'); M.nextTurn('B');
    t.ok(g.mustAttack(bird), 'Rendmaw: still goaded on B\'s later turn');
    t.eq(g._goaders(bird).join(), 'A');
    const other = M.bf('B', 'Grizzly Bears');
    t.no(g.mustAttack(other), 'Rendmaw: only the tokens');
  });
