  test('Commanders: Coram, the Undertaker — +X/+0 for the greatest power in graveyards; attacks: each mills; a land and a spell from among the milled', (mk, t) => {
    t.auto('Coram, the Undertaker');
    const M = mk({ library: Array(30).fill('Island'), life: 40 });
    const g = M.g;
    const coram = M.bf('A', 'Coram, the Undertaker');
    t.eq(g.powerOf(coram), 0, 'Coram: nothing in the graveyards');
    const wurm = M.grave('B', 'Craw Wurm');
    g.bumpBoard();
    t.eq(g.powerOf(coram), 6, "Coram: Craw Wurm's 6 in B's graveyard");
    const forest = M.top('A', 'Forest'), bears = M.top('B', 'Grizzly Bears');
    M.top('B', 'Hill Giant');
    M.answer('declareAttackers', () => [{ attackerId: coram.id, defenderId: 'B' }]);
    M.toMain('A', 'declareBlockers');
    t.zone(forest, 'graveyard', 'Coram: A mills');
    const hill = M.zone('B', 'graveyard').find(o => o.name === 'Hill Giant');
    t.ok(hill, 'Coram: B mills');
    for (let i = 0; i < 80 && !(g.phase.id === 'postcombat' && g.step === 'main' && !g.stack.length && g.priorityPlayer.id === 'A'); i++) {
      M.settle(); g.passPriority(g.priorityPlayer.id, true);
    }
    M.mana('A', 'R6');
    t.no(g.castSpell('A', wurm.id, { auto: true }), 'Coram: not a card put there some other way');
    t.ok(g.playableNow('A').some(a => a.objId === hill.id), "Coram: Hill Giant in B's graveyard is offered");
    t.ok(g.playableNow('A').some(a => a.objId === forest.id && a.kind === 'land'), 'Coram: and the Forest');
    t.ok(g.playLand('A', forest.id), g.lastError);
    t.zone(forest, 'battlefield', 'Coram: a land from among them');
    t.ok(g.castSpell('A', hill.id, { auto: true }), g.lastError);
    M.resolve();
    t.zone(hill, 'battlefield', "Coram: a spell from B's graveyard");
    t.eq(hill.controller, 'A', 'Coram: under A\'s control');
  });
