    const bear = M.bf('A', 'Grizzly Bears');
    const theirs = M.bf('B', 'Grizzly Bears');
    M.activate('A', tri, 0);
    for (const c of big) t.zone(c, 'exile', 'The Capitoline Triad: ' + c.name + ' exiled');
    t.zone(wurm, 'graveyard', 'The Capitoline Triad: not Craw Wurm, which is not historic');
    t.eq(g.powerOf(bear), 9, 'The Capitoline Triad: Grizzly Bears 9/9');
    t.eq(g.toughnessOf(bear), 9);
    t.eq(g.powerOf(tri), 9, 'The Capitoline Triad: itself too');
    t.eq(g.powerOf(theirs), 2, "The Capitoline Triad: not B's");
