    const bs = M.bf('A', 'Bonesplitter');
    bs.attachedTo = bear.id; bear.attachments = [bs.id];
    const giant = M.bf('A', 'Hill Giant');
    g.bumpBoard();
    M.answer('declareAttackers', () => [{ attackerId: bear.id, defenderId: 'B' }, { attackerId: giant.id, defenderId: 'B' }]);
    M.toMain('A', 'declareBlockers');
    t.eq(bear.counters['+1/+1'], 2, 'Arna: one +1/+1 counter doubled to two');
    const copies = M.bfOf('A').filter(o => o.isToken && o.name === 'Bonesplitter');
    t.eq(copies.length, 1, 'Arna: a token copy of Bonesplitter');
    t.eq(copies[0] && copies[0].attachedTo, bear.id, 'Arna: attached to the Bears');
    t.eq(g.powerOf(bear), 8, 'Arna: 2 + 2 counters + 2 + 2');
    t.eq(g.powerOf(giant), 3, 'Arna: Hill Giant is not modified');
