  test("Commanders: Henrika Domnathi — draw and lose 1, then transform; Henrika, Infernal Seer pumps her kind", (mk, t) => {
    const M = mk({ library: Array(30).fill('Island') });
    const g = M.g;
    const hen = M.bf('A', 'Henrika Domnathi');
    let opts = null;
    M.answer('mode', (ch) => { opts = ch.options.map(o => o.i); return { modes: [1] }; });
    const hand = M.zone('A', 'hand').length;
    M.toMain('A', 'beginCombat'); M.resolve();
    t.eq(M.zone('A', 'hand').length, hand + 1, 'Henrika: drew a card');
    t.eq(M.life('A'), 19, 'Henrika: lost 1 life');
    t.eq(opts && opts.length, 3, 'Henrika: three modes the first time');
    M.nextTurn('A');
    M.answer('mode', (ch) => { opts = ch.options.map(o => o.i); return { modes: [0] }; });
    M.toMain('A', 'beginCombat'); M.resolve();
    t.eq(opts.join(), '0,2', 'Henrika: the draw is gone');
    t.zone(hen, 'graveyard', 'Henrika: sacrificed herself');
    // a fresh Henrika has her own modes; the third time on one Henrika, nothing is asked
    const h2 = M.bf('A', 'Henrika Domnathi');
    h2._usedModes = { key: 'ever', list: [0, 1] };
    M.nextTurn('A');
    const before = M.asked.filter(ch => ch.type === 'mode').length;
    M.toMain('A', 'beginCombat'); M.resolve();
    t.eq(M.asked.filter(ch => ch.type === 'mode').length, before, 'Henrika: one mode left — no question');
    t.eq(h2.name, 'Henrika, Infernal Seer', 'Henrika: transformed');
    const bear = M.bf('A', 'Grizzly Bears'), bird = M.bf('A', 'Suntail Hawk'), vamp = M.bf('A', 'Vampire Nighthawk');
    M.mana('A', 'BBB');
    M.activate('A', h2, 0);
    t.eq(g.powerOf(h2), 4, 'Infernal Seer: flying, deathtouch and lifelink: +1/+0');
    t.eq(g.powerOf(bird), 2, 'Infernal Seer: Suntail Hawk flies');
    t.eq(g.powerOf(vamp), 3, 'Infernal Seer: Vampire Nighthawk');
    t.eq(g.powerOf(bear), 2, 'Infernal Seer: not Grizzly Bears');
  });
