  test("Commanders: Frodo, Sauron's Bane — Citizen to Scout to Rogue, each only from the one before", (mk, t) => {
    t.auto("Frodo, Sauron's Bane");
    const M = mk({ library: Array(30).fill('Island') });
    const g = M.g;
    const frodo = M.bf('A', "Frodo, Sauron's Bane");
    M.mana('A', 'BBB');
    M.activate('A', frodo, 1);
    t.eq(g.powerOf(frodo), 1, 'Frodo: a Citizen is not a Scout — nothing');
    t.no(g._hasSubtype(frodo, 'Rogue'));
    M.mana('A', 'WB');
    M.activate('A', frodo, 0);
    t.eq(g.powerOf(frodo) + '/' + g.toughnessOf(frodo), '2/3', 'Frodo: a 2/3 Scout');
    t.ok(g.hasKw(frodo, 'lifelink'), 'Frodo: with lifelink');
    t.ok(g._hasSubtype(frodo, 'Scout') && g._hasSubtype(frodo, 'Halfling') && !g._hasSubtype(frodo, 'Citizen'), 'Frodo: a Halfling Scout, no longer a Citizen');
    M.nextTurn('A');
    t.ok(g._hasSubtype(frodo, 'Scout') && g.hasKw(frodo, 'lifelink'), 'Frodo: for good');
    M.mana('A', 'BBB');
    M.activate('A', frodo, 1);
    t.ok(g._hasSubtype(frodo, 'Rogue') && !g._hasSubtype(frodo, 'Scout'), 'Frodo: a Halfling Rogue');
    t.eq(g.powerOf(frodo) + '/' + g.toughnessOf(frodo), '2/3', 'Frodo: still 2/3');
    t.ok(g.hasKw(frodo, 'lifelink'), 'Frodo: still lifelink');
    // combat damage: the Ring tempts A while it has tempted fewer than four times
    M.answer('declareAttackers', () => [{ attackerId: frodo.id, defenderId: 'B' }]);
    M.toMain('A', 'endCombat'); M.resolve();
    t.eq(M.life('B'), 18);
    t.eq(g.player('A').ringLevel, 1, 'Frodo: the Ring tempts you');
    t.no(g.player('B').hasLost, 'Frodo: B is still in it');
    g.player('A').ringLevel = 4;
    M.nextTurn('A');
    M.answer('declareAttackers', () => [{ attackerId: frodo.id, defenderId: 'B' }]);
    M.toMain('A', 'endCombat'); M.resolve();
    t.ok(g.player('B').hasLost || g.over, 'Frodo: the Ring has tempted A four times — B loses the game');
  });
