  test('Commanders: Kamiz, Obscura Oculus — you attack: target attacker unblockable and connives; another with lesser power gets double strike', (mk, t) => {
    t.auto('Kamiz, Obscura Oculus');
    const M = mk({ library: Array(30).fill('Island') });
    const g = M.g;
    M.toMain('A');
    M.bf('A', 'Kamiz, Obscura Oculus');
    const giant = M.bf('A', 'Hill Giant'), bear = M.bf('A', 'Grizzly Bears'), elf = M.bf('A', 'Llanowar Elves'), wurm = M.bf('A', 'Craw Wurm');
    M.hand('A', 'Lightning Bolt');
    const wall = M.bf('B', 'Wall of Stone');
    M.answer('declareAttackers', () => [giant, bear, elf, wurm].map(o => ({ attackerId: o.id, defenderId: 'B' })));
    M.answer('pickTarget', (ch) => ({ targets: ((ch.options || [])[0] || []).filter(x => x.id === giant.id) }));
    let offered = null;
    const pick = (ch) => {
      if (ch.purpose === 'connive') return { picks: [ch.items.find(i => (g.obj(i.id) || {}).name === 'Lightning Bolt').id] };
      offered = ch.items.map(i => i.id);
      return { picks: [bear.id] };
    };
    M.answer('choose', pick); M.answer('choose', pick);
    M.answer('declareBlockers', () => [{ blockerId: wall.id, attackerIds: [wurm.id] }]);
    M.toMain('A', 'declareBlockers');
    t.eq(giant.counters['+1/+1'], 1, 'Kamiz: Hill Giant connived — a nonland card discarded, a counter');
    t.no(g.canBlock(wall, giant), "Kamiz: the Giant can't be blocked");
    t.ok(offered && offered.includes(bear.id) && offered.includes(elf.id), 'Kamiz: the Bears and the Elves have lesser power');
    t.no(offered && (offered.includes(wurm.id) || offered.includes(giant.id)), 'Kamiz: not the Wurm, nor the target');
    M.toMain('A', 'end');
    t.eq(M.life('B'), 20 - 4 - 4 - 1, 'Kamiz: the Giant (4), the Bears with double strike (4), the Elves 1; the Wurm blocked');
  });
