    const kotis = M.bf('A', 'Kotis, Sibsig Champion');
    const bear = M.grave('A', 'Grizzly Bears');
    const elf = M.grave('A', 'Llanowar Elves');
    const bolt = M.grave('A', 'Lightning Bolt');
    const isles = [0, 1, 2].map(() => M.grave('A', 'Island'));
    const use = (o) => g.altUsesFor('A', o.id).find(u => u.via === 'graveExile');
    t.ok(use(bear), 'Kotis: a creature card in the graveyard may be cast');
    t.no(use(bolt), 'Kotis: not an instant');
