    M.answer('choose', (ch) => { t.eq(ch.purpose, 'exileGrave', 'Kotis: which three, asked'); t.eq(ch.items.length, 5, 'Kotis: from the five others'); return { picks: isles.map(x => x.id) }; });
    M.mana('A', '1G'); M.cast('A', bear, { via: 'graveExile' });
    t.zone(bear, 'battlefield', 'Kotis: cast from the graveyard');
    t.eq(M.zone('A', 'exile').length, 3, 'Kotis: three other cards exiled');
    t.ok(isles.every(x => x.zone === 'exile'), 'Kotis: the three chosen');
    t.eq(kotis.counters['+1/+1'] || 0, 2, 'Kotis: two counters for a creature cast from a graveyard');
