  test('Commanders: Círdan the Shipwright — secret council: a card for each vote received; those with none may put a permanent card onto the battlefield', (mk, t) => {
    t.auto('Círdan the Shipwright');
    const M = mk({ players: ['A', 'B', 'C'], library: Array(30).fill('Island') });
    const g = M.g;
    const cirdan = M.hand('A', 'Círdan the Shipwright');
    const bear = M.hand('C', 'Grizzly Bears');
    M.hand('C', 'Lightning Bolt');
    const votes = { A: 'A', B: 'A', C: 'B' };
    const told = [];
    for (let i = 0; i < 3; i++) M.answer('choose', (ch) => {
      t.eq(ch.purpose, 'votePlayer', 'Círdan: a vote for a player');
      told.push(g.log.some(l => / voted for /.test(l.text)));
      return { picks: [votes[ch.playerId]] };
    });
    M.answer('pickCard', (ch) => { t.eq(ch.playerId, 'C', 'Círdan: C got no votes'); t.eq(ch.cards.map(c => c.name).join(), 'Grizzly Bears', 'Círdan: permanent cards only'); return { cardIds: [bear.id] }; });
    const hands = () => ['A', 'B', 'C'].map(id => M.zone(id, 'hand').length);
    const before = hands();
    M.mana('A', '3GU'); M.cast('A', cirdan);
    t.no(told.some(Boolean), 'Círdan: no vote told before all are in');
    const after = hands();
    t.eq(after[0], before[0] - 1 + 2, 'Círdan: A, two votes — two cards');
    t.eq(after[1], before[1] + 1, 'Círdan: B, one vote — one card');
    t.zone(bear, 'battlefield', 'Círdan: C put the Bears onto the battlefield');
    t.eq(bear.controller, 'C', 'Círdan: under C\'s control');
    t.no(M.asked.some(c => c.type === 'pickCard' && c.playerId !== 'C'), 'Círdan: only those with no votes are asked');
  });
