    const g = M.g;
    const bear = M.bf('A', 'Grizzly Bears'), giant = M.bf('A', 'Hill Giant'), elf = M.bf('A', 'Llanowar Elves');
    M.answer('pickTarget', () => ({ targets: [{ kind: 'object', id: bear.id }] }));
    M.put('A', 'Urdnan, Dromoka Warrior', 'battlefield', { etb: true });
    M.resolve();
    t.eq(bear.counters['+1/+1'], 1, 'Urdnan: a counter on the Bears');
    g.addCounters(giant, '+1/+1', 2);
    let opts = null;
    M.answer('declareAttackers', () => [bear, giant, elf].map(o => ({ attackerId: o.id, defenderId: 'B' })));
    M.answer('pickTarget', (ch) => { opts = (ch.options || []).map(l => l.map(x => x.id)); return { targets: [{ kind: 'object', id: bear.id }] }; });
    M.toMain('A', 'declareBlockers'); M.resolve();
    t.ok(opts && !opts.flat().includes(elf.id) && opts.flat().includes(giant.id), 'Urdnan: only an attacker with a counter');
    t.ok(g.hasKw(bear, 'First Strike') && !g.hasKw(bear, 'Double Strike'), 'Urdnan: one counter — first strike');
    M.nextTurn('A');
    M.answer('declareAttackers', () => [giant].map(o => ({ attackerId: o.id, defenderId: 'B' })));
    M.answer('pickTarget', () => ({ targets: [{ kind: 'object', id: giant.id }] }));
    M.toMain('A', 'declareBlockers'); M.resolve();
    t.ok(g.hasKw(giant, 'Double Strike'), 'Urdnan: two counters — double strike instead');
    t.no(g.hasKw(bear, 'First Strike'), 'Urdnan: the Bears\' first strike ended with the turn');
