  test('Commanders: Raph & Leo, Sibling Rivals — first combat: untap one or two attackers, then an additional combat phase; not again in that one', (mk, t) => {
    t.auto('Raph & Leo, Sibling Rivals');
    const M = mk({ library: Array(30).fill('Plains') });
    const g = M.g;
    M.toMain('A');
    const rl = M.bf('A', 'Raph & Leo, Sibling Rivals');
    const bear = M.bf('A', 'Grizzly Bears');
    let picked = null;
    M.answer('pickTarget', (ch) => { picked = ch; return { targets: [(ch.options[0] || []).find(x => x.id === rl.id), (ch.options[1] || []).find(x => x.id === bear.id)] }; });
    M.answer('declareAttackers', () => [{ attackerId: rl.id, defenderId: 'B' }, { attackerId: bear.id, defenderId: 'B' }]);
    M.toMain('A', 'endCombat');
    t.no(rl.tapped, 'Raph & Leo: untapped'); t.no(bear.tapped, 'Raph & Leo: the Bears untapped too');
    t.eq(M.life('B'), 16);
    M.answer('declareAttackers', () => [{ attackerId: rl.id, defenderId: 'B' }, { attackerId: bear.id, defenderId: 'B' }]);
    for (let k = 0; k < 60 && !(g.combatsThisTurn >= 2 && g.step === 'endCombat'); k++) { M.settle(); g.passPriority(g.priorityPlayer.id, true); }
    M.settle();
    t.eq(g.combatsThisTurn, 2, 'Raph & Leo: an additional combat phase');
    t.eq(M.life('B'), 12, 'Raph & Leo: both attack again');
    t.ok(rl.tapped && bear.tapped, 'Raph & Leo: second combat — no untap, not the first combat phase');
    for (let k = 0; k < 30 && g.phase.id !== 'postcombat'; k++) { M.settle(); g.passPriority(g.priorityPlayer.id, true); }
    t.eq(g.phase.id, 'postcombat', 'Raph & Leo: no third combat');
    t.eq(M.manualLines().length, 0);
  });
