  test('Escape: which other cards are exiled is chosen, asked only when there are more than needed; a bot exiles its least useful', (mk, t) => {
    t.auto('Woe Strider');
    const M = mk({ library: Array(30).fill('Island') });
    const g = M.g;
    const w = M.grave('A', 'Woe Strider');
    const isles = [0, 1, 2, 3].map(() => M.grave('A', 'Island'));
    const keep = ['Lightning Bolt', 'Shivan Dragon'].map(n => M.grave('A', n));
    M.answer('choose', (ch) => { t.eq(ch.purpose, 'exileGrave', 'escape: which four, asked'); t.eq(ch.items.length, 6, 'escape: from the six others'); return { picks: isles.map(x => x.id) }; });
    M.mana('A', '3BB'); M.cast('A', w, { via: 'escape' });
    t.zone(w, 'battlefield', 'escape: Woe Strider escaped');
    t.ok(isles.every(x => x.zone === 'exile'), 'escape: the four chosen exiled');
    t.ok(keep.every(x => x.zone === 'graveyard'), 'escape: the others stay');
    const M2 = mk({ library: Array(30).fill('Island') });
    const w2 = M2.grave('A', 'Woe Strider');
    [0, 1, 2, 3].forEach(() => M2.grave('A', 'Island'));
    M2.mana('A', '3BB'); M2.cast('A', w2, { via: 'escape' });
    t.no(M2.asked.some(ch => ch.purpose === 'exileGrave'), 'escape: exactly four others — nothing asked');
    t.eq(M2.zone('A', 'exile').length, 4, 'escape: all four exiled');
    const M3 = mk({ library: Array(30).fill('Island') });
    M3.player('A').isBot = true;
    const w3 = M3.grave('A', 'Woe Strider');
    const isles3 = [0, 1, 2, 3].map(() => M3.grave('A', 'Island'));
    const dragon = M3.grave('A', 'Shivan Dragon');
    M3.g.zones.A.graveyard.splice(M3.g.zones.A.graveyard.indexOf(dragon), 1);
    M3.g.zones.A.graveyard.splice(1, 0, dragon);
    M3.mana('A', '3BB'); M3.cast('A', w3, { via: 'escape' });
    t.zone(w3, 'battlefield', 'escape (bot): escaped');
    t.zone(dragon, 'graveyard', 'escape (bot): Shivan Dragon kept, the Islands exiled');
    t.ok(isles3.every(x => x.zone === 'exile'), 'escape (bot): four Islands exiled');
  });
