  test('Commanders: Nine-Fingers Keene — combat damage: a Gate from the top nine onto the battlefield; the rest to hand with nine Gates, else to the bottom', (mk, t) => {
    t.auto('Nine-Fingers Keene');
    const run = (gates) => {
      const M = mk({ library: Array(30).fill('Island') });
      const g = M.g;
      const keene = M.bf('A', 'Nine-Fingers Keene');
      keene.summoningSick = false;
      for (let i = 0; i < gates; i++) M.bf('A', 'Azorius Guildgate');
      const tops = [];
      for (let i = 0; i < 8; i++) tops.push(M.top('A', 'Forest'));
      const gate = M.top('A', 'Golgari Guildgate');
      const hand0 = M.zone('A', 'hand').length;
      M.answer('declareAttackers', () => [{ attackerId: keene.id, defenderId: 'B' }]);
      M.toMain('A', 'endCombat');
      return { M, g, gate, tops, hand0 };
    };
    const a = run(8);
    t.zone(a.gate, 'battlefield', 'Keene: the Gate put onto the battlefield');
    t.ok(a.tops.every(o => o.zone === 'hand'), 'Keene: nine Gates — the other eight into the hand');
    t.eq(a.M.zone('A', 'hand').length, a.hand0 + 8);
    const b = run(0);
    t.zone(b.gate, 'battlefield', 'Keene: the Gate put onto the battlefield');
    t.ok(b.tops.every(o => o.zone === 'library'), 'Keene: one Gate — the rest stay in the library');
    const lib = b.M.zone('A', 'library');
    t.ok(b.tops.every(o => lib.indexOf(o) >= lib.length - 8), 'Keene: on the bottom');
    t.eq(b.M.zone('A', 'hand').length, b.hand0, 'Keene: none into the hand');
  });
