    let n = hand();
    M.mana('A', 'R');
    M.cast('A', M.hand('A', 'Shock'), { targets: [{ kind: 'player', id: 'B' }] });
    t.eq(hand(), n, 'Loki: a spell — nothing');
    M.activate('A', pyro, 0, { targets: [{ kind: 'player', id: 'B' }] });
    t.eq(hand(), n + 1, 'Loki: an activated ability aimed at a player — a card');
    pyro.tapped = false;
