    M.activate('B', bp, 0, { targets: [{ kind: 'player', id: 'A' }] });
    t.eq(hand(), n, 'Loki: an opponent\'s ability — nothing');
    M.nextTurn('A');
    const bear = M.bf('B', 'Grizzly Bears');
    n = hand();
    M.mana('A', 'RR3');
    M.answer('pickTarget', { targets: [{ kind: 'object', id: bear.id }] });
    M.cast('A', M.hand('A', 'Flametongue Kavu'));
