    t.zone(bears, 'exile', 'Urianger: the top card exiled');
    t.ok(bears.faceDownExile, 'Urianger: face down');
    t.eq(bears.exiledWithId, ur.id, 'Urianger: exiled with Urianger');
    t.no(g.canCast('A', bears.id).ok, 'Urianger: not playable yet');
    M.nextTurn('A');
