    M.answer('pickCard', (ch) => ({ cardIds: ch.cards.map(c => c.id) }));
    ur.tapped = false;
    M.activate('A', ur, 0);
    t.zone(forest, 'exile', 'Urianger: a Forest exiled too');
    ur.tapped = false;
    M.activate('A', ur, 1);
    const life = g.player('A').life;
    M.playLand('A', forest);
    t.zone(forest, 'battlefield', 'Urianger: a land played from exile');
    t.eq(g.player('A').life, life + 2, 'Urianger: 2 life for the land');
