    const gal = M.hand('A', 'Galactus, Devourer of Worlds');
    M.cast('A', gal, { resolve: false });
    M.answer('pickTarget', (ch) => ({ targets: [(ch.options[0] || []).find(x => x.id === ring.id)] }));
    M.resolve();
