    for (let i = 0; i < 20 && !(g.pendingChoice && g.pendingChoice.type === 'declareAttackers'); i++) g.passPriority(g.priorityPlayer.id, true);
    t.no(g.declareAttackers('A', []), 'Galactus: must attack');
