  test('Commanders: Bruce Banner // The Incredible Hulk — draw X; transform; dealt damage while attacking: a counter, untapped, another combat', (mk, t) => {
    t.auto('Bruce Banner // The Incredible Hulk');
    const M = mk({ library: Array(30).fill('Island') });
    const g = M.g;
    M.toMain('A');
    const bb = M.bf('A', 'Bruce Banner // The Incredible Hulk'); bb.summoningSick = false;
    M.mana('A', '4');
    M.activate('A', bb, 0, { x: 2 });
    t.eq(M.zone('A', 'hand').length, 2, 'Bruce Banner: X=2, two cards');
    bb.tapped = false;
    M.mana('A', '2RRGG');
    M.activate('A', bb, 1);
    t.eq(bb.face, 1, 'Bruce Banner: transformed');
    t.ok(/Hulk/.test(bb.name), 'Bruce Banner: now The Incredible Hulk');
    const p0 = g.powerOf(bb);
    // a Bolt outside combat: a counter, no more
    M.mana('A', 'R');
    M.cast('A', M.hand('A', 'Lightning Bolt'), { targets: [bb] });
    t.eq(bb.counters['+1/+1'], 1, 'Hulk: a counter for the damage');
    t.eq(g.powerOf(bb), p0 + 1);
    t.eq((g._extraPhases || []).length, 0, 'Hulk: not attacking, no extra combat');
    // attacking, blocked: dealt damage, untapped, another combat
    const wall = M.bf('B', 'Grizzly Bears');
    let combats = 0;
    M.answer('declareAttackers', (ch) => { combats++; return combats === 1 ? [{ attackerId: bb.id, defenderId: 'B' }] : []; });
    M.answer('declareBlockers', () => [{ blockerId: wall.id, attackerIds: [bb.id] }]);
    M.answer('declareAttackers', (ch) => { combats++; t.ok(ch.candidates.includes(bb.id), 'Hulk: untapped, may attack again'); return []; });
    for (let i = 0; i < 60 && combats < 2; i++) { M.settle(); if (!g.priorityPlayer) break; g.passPriority(g.priorityPlayer.id, true); }
    t.eq(combats, 2, 'Hulk: a second combat phase');
    t.eq(bb.counters['+1/+1'], 2, 'Hulk: another counter');
    t.eq(M.manualLines().length, 0);
  });
