    M.answer('confirm', { yes: true });
    g.moveObject(bear, 'graveyard');
    M.resolve();
    t.zone(bear, 'exile', 'Brenard: the Bears exiled');
    const tok = M.bfOf('A').find(o => o.isToken && o.name === 'Grizzly Bears');
    t.ok(tok, 'Brenard: a token copy');
    t.ok(/Artifact Creature/.test(tok.card.type_line) && /Food/.test(tok.card.type_line) && /Golem/.test(tok.card.type_line) && /Bear/.test(tok.card.type_line), 'Brenard: a Food Golem artifact creature, still a Bear');
    t.eq(g.powerOf(tok), 3, 'Brenard: 1/1, +2/+2 as a Food or Golem');
    t.eq(g.toughnessOf(tok), 3);
    t.ok(g.hasKw(tok, 'trample'), 'Brenard: and trample');
    // the token's own ability: {2}, {T}, sacrifice: 3 life
    tok.summoningSick = false;
    const a = tok.analysis();
    const idx = a.abilities.filter(x => x.kind === 'activated').findIndex(x => /gain 3 life/i.test(x.text || ''));
    t.ok(idx >= 0, 'Brenard: the token has the life ability');
