  test('Commanders: Zilortha, Strength Incarnate — the table\'s combat preview judges lethal damage by power too', (mk, t) => {
    t.auto('Zilortha, Strength Incarnate');
    // the preview (src/12b-ui-table-fx.js predictCombat) on its own, against a stand-in table
    const fs = require('fs'), path = require('path'), vm = require('vm');
    const MTG = { el() {}, util: {}, ui: { Table: Object.assign(function () {}, { helpers: {} }) } };
    vm.runInNewContext(fs.readFileSync(path.join(__dirname, '../../src/12b-ui-table-fx.js'), 'utf8'), { window: { MTG }, setTimeout, Promise });
    const predict = (g, me) => MTG.ui.Table.prototype.predictCombat.call({ view: g.viewFor(me), live: null, meId: me });
    const M = mk({ library: Array(30).fill('Mountain') });
    const g = M.g;
    const z = M.bf('A', 'Zilortha, Strength Incarnate');
    const wall = M.bf('A', 'Wall of Omens');
    const giant = M.bf('B', 'Hill Giant');
    const bears = M.bf('B', 'Grizzly Bears');
    t.ok(g.viewFor('A').battlefield.find(o => o.id === wall.id).lethalByPower, 'Zilortha: the view says so of A\'s creatures');
    t.no(g.viewFor('A').battlefield.find(o => o.id === giant.id).lethalByPower, 'Zilortha: not of B\'s');
    M.nextTurn('A');
    M.answer('declareAttackers', () => [{ attackerId: z.id, defenderId: 'B' }]);
    M.answer('declareBlockers', () => [{ blockerId: giant.id, attackerIds: [z.id] }]);
    M.toMain('A', 'declareBlockers');
    let p = predict(g, 'A');
    t.no(p.dies.has(z.id), 'Zilortha: 3 damage to a 7-power Zilortha — not doomed');
    t.ok(p.dies.has(giant.id), 'Zilortha: the Giant blocking it is');
    M.nextTurn('B');
    M.answer('declareAttackers', () => [{ attackerId: bears.id, defenderId: 'A' }]);
    M.answer('declareBlockers', () => [{ blockerId: wall.id, attackerIds: [bears.id] }]);
    M.toMain('B', 'declareBlockers');
    p = predict(g, 'A');
    t.ok(p.dies.has(wall.id), 'Zilortha: 2 damage to a 0-power Wall — doomed');
    t.no(p.dies.has(bears.id), 'Zilortha: the Bears it blocks take nothing');
  });
  test('Commanders: Lita, Mechanical Engineer — {3}{W}, {T}: a 5/5 flying Vehicle named Zeppelin with crew 3; end step untaps other artifact creatures', (mk, t) => {
    t.auto('Lita, Mechanical Engineer');
    const M = mk({ library: Array(30).fill('Plains') });
    const g = M.g;
    M.toMain('A');
    const lita = M.bf('A', 'Lita, Mechanical Engineer');
    const golem = M.bf('A', 'Bronze Sable');
    const giant = M.bf('A', 'Hill Giant');
    M.mana('A', '3W');
    M.activate('A', lita, 0);
    M.resolve();
    const zep = M.bfOf('A').find(o => o.isToken);
    t.ok(zep, 'Lita: a token');
    t.eq(zep.name, 'Zeppelin', 'Lita: named Zeppelin');
    t.no(g.characteristics(zep).isCreature, 'Lita: no creature until crewed');
    t.ok((zep.analysis().subtypes || []).includes('Vehicle'), 'Lita: a Vehicle');
    t.ok(lita.tapped, 'Lita: tapped for it');
    const all = zep.analysis().manaAbilities.concat(zep.analysis().abilities.filter(a => a.kind === 'activated'));
    const i = all.findIndex(a => a.text === 'Crew 3');
    t.ok(i >= 0, 'Lita: crew 3');
    M.activate('A', zep, i, { tapIds: [giant.id] });
    t.ok(g.characteristics(zep).isCreature, 'Lita: crewed, a creature');
    t.eq(g.powerOf(zep), 5);
    t.ok(g.hasKw(zep, 'flying'), 'Lita: with flying');
    golem.tapped = true;
    M.toMain('A', 'end'); M.resolve();
    t.no(golem.tapped, 'Lita: the artifact creature untaps at her end step');
    t.ok(giant.tapped, 'Lita: a nonartifact creature stays tapped');
    t.ok(lita.tapped, 'Lita: not herself');
  });
