  test('Commanders: villainous choice — each opponent in turn order, what one chose done before the next chooses (CR 701.55)', (mk, t) => {
    const M = mk({ library: Array(30).fill('Island'), players: ['A', 'B', 'C'] });
    const g = M.g;
    M.bf('A', 'Davros, Dalek Creator');
    const bcard = M.hand('B', 'Grizzly Bears');
    M.hand('C', 'Hill Giant');
    g.changeLife('B', -3); g.changeLife('C', -3);
    const handA = M.zone('A', 'hand').length;
    const seen = [];
    // B discards; C, seeing B's card already gone, lets A draw instead
    const pick = (ch) => {
      seen.push({ who: ch.playerId, bGone: bcard.zone === 'graveyard' });
      return { picks: [ch.playerId === 'B' ? 1 : (bcard.zone === 'graveyard' ? 0 : 1)] };
    };
    M.answer('choose', pick); M.answer('choose', pick);
    M.toMain('A', 'end'); M.resolve();
    t.eq(seen.map(x => x.who).join(','), 'B,C', 'villainous: B first, then C');
    t.ok(seen[1] && seen[1].bGone, "villainous: B's discard done before C chooses");
    t.zone(bcard, 'graveyard');
    t.eq(M.zone('C', 'hand').length, 1, 'villainous: C chose the draw, keeping the card');
    t.eq(M.zone('A', 'hand').length, handA + 1, 'villainous: A drew once');
  });
