    t.ok(g.altUsesFor('A', orn.id).some(u => u.via === 'unearth' && u.cost === '{1}{B}{R}'), 'Mishra: an artifact card has unearth');
    t.no(g.altUsesFor('A', bear.id).some(u => u.via === 'unearth'), 'Mishra: not a creature card');
    M.mana('A', 'BR1');
    M.cast('A', orn, { via: 'unearth' });
    t.eq(orn.zone, 'battlefield', 'Mishra: unearthed');
    t.ok(g.hasKw(orn, 'haste'), 'unearth: it gains haste');
    M.nextTurn('B');
    t.eq(orn.zone, 'exile', 'unearth: exiled at the next end step');
    // B's Bolt at Mishra: ward — B sacrifices a permanent, and the Bolt resolves
    const mo = M.bf('B', 'Mountain');
    M.answer('choose', (ch) => { t.eq(ch.purpose, 'wardPay', 'Mishra: ward asks B'); return { picks: [mo.id] }; });
    M.mana('B', 'R');
    M.cast('B', M.hand('B', 'Lightning Bolt'), { targets: [mi] });
    t.eq(mo.zone, 'graveyard', 'Mishra: ward — B sacrificed a permanent');
