    t.eq(M.life('A'), 21, 'Ob Nixilis: A gains what was lost');
    M.nextTurn('A');
    ob.counters.loyalty = 8;
    M.activate('A', ob, 2);
    const em = M.zone('A', 'command').find(o => /Emblem/.test(o.name));
    t.ok(em, 'Ob Nixilis: an emblem in the command zone');
