  test('Commanders: Bruna, Light of Alabaster — attacking, Auras from the battlefield, the graveyard and the hand go on her in one pick', (mk, t) => {
    t.auto('Bruna, Light of Alabaster');
    const M = mk({ library: Array(30).fill('Plains') });
    const g = M.g;
    M.toMain('A');
    const bruna = M.bf('A', 'Bruna, Light of Alabaster');
    const bear = M.bf('A', 'Grizzly Bears');
    const rancor = M.bf('A', 'Rancor');
    g._attachAura(rancor, bear);
    const theirs = M.bf('B', 'Grizzly Bears');
    const holy = M.bf('B', 'Holy Strength');
    g._attachAura(holy, theirs);
    const unholy = M.grave('A', 'Unholy Strength');
    const armor = M.hand('A', 'Spirit Link');
    const curse = M.hand('A', 'Curse of the Pierced Heart');
    const left = M.grave('A', 'Pacifism');
    let offered = null;
    M.answer('choose', (ch) => { offered = ch.items.map(x => x.id); return { picks: [rancor.id, holy.id, unholy.id, armor.id] }; });
    M.answer('declareAttackers', () => [{ attackerId: bruna.id, defenderId: 'B' }]);
    M.toMain('A', 'declareBlockers');
    t.ok(offered && !offered.includes(curse.id), 'Bruna: a Curse can\'t enchant her');
    t.ok(offered.includes(left.id), 'Bruna: every Aura card that could enchant her is offered');
    t.eq(rancor.attachedTo, bruna.id, 'Bruna: Rancor moved over');
    t.eq(holy.attachedTo, bruna.id, 'Bruna: their Holy Strength too');
    t.eq(holy.controller, 'B', 'Bruna: still theirs');
    t.zone(unholy, 'battlefield'); t.eq(unholy.attachedTo, bruna.id, 'Bruna: Unholy Strength from the graveyard');
    t.zone(armor, 'battlefield'); t.eq(armor.attachedTo, bruna.id, 'Bruna: Spirit Link from the hand');
    t.zone(left, 'graveyard', 'Bruna: Pacifism not picked');
    t.eq(g.powerOf(bruna), 5 + 2 + 1 + 2, 'Bruna: Rancor, Holy and Unholy Strength');
    t.eq(M.manualLines().length, 0);
  });
