    t.ok(elfOf(sliver), 'Rukarumel: a Sliver token is an Elf');
    t.ok(elfOf(ru), 'Rukarumel: and itself');
    M.g._runEffects([{ op: 'createToken', n: 1, pt: '1/1', colorWords: ['white'], subtypes: 'Soldier', keywords: [], addTypes: [] }], { controller: 'A', obj: ru, name: 'test', kind: 'ability' });
