  test('Commanders: Rip, Spawn Hunter — tapped at the second main phase, reveal its power in cards, creatures and Vehicles of different powers', (mk, t) => {
    t.auto('Rip, Spawn Hunter');
    const M = mk({ library: Array(30).fill('Forest') });
    const g = M.g;
    M.toMain('A');
    const rip = M.bf('A', 'Rip, Spawn Hunter');
    const toMain2 = () => { for (let i = 0; i < 40 && !(g.phase.id === 'postcombat' && !g.stack.length && !g.pendingChoice); i++) { M.settle(); g.passPriority(g.priorityPlayer.id, true); } };
    // untapped: nothing
    let asked = 0;
    M.answer('choose', (ch) => { asked++; return { picks: [] }; });
    toMain2();
    t.eq(asked, 0, 'Rip: untapped, nothing revealed');
    M.answers.length = 0;
    M.nextTurn('A');
    const lib = M.zone('A', 'library');
    const b1 = M.put('A', 'Grizzly Bears', 'library'), b2 = M.put('A', 'Grizzly Bears', 'library');
    const hg = M.put('A', 'Hill Giant', 'library'), isl = M.put('A', 'Island', 'library');
    // (top four: the Island, the Giant and the two Bears; a fifth card stays where it is)
    lib.splice(lib.indexOf(isl), 1); lib.unshift(isl);
    lib.splice(lib.indexOf(hg), 1); lib.unshift(hg);
    lib.splice(lib.indexOf(b2), 1); lib.unshift(b2);
    lib.splice(lib.indexOf(b1), 1); lib.unshift(b1);
    const fifth = lib[4];
    rip.tapped = true;
    M.answer('choose', (ch) => {
      t.eq(ch.purpose, 'distinctPower');
      t.eq(ch.items.map(i => i.name).sort().join(), 'Grizzly Bears,Grizzly Bears,Hill Giant', 'Rip: the creatures among four cards, not the Island');
      t.eq(g.resolveChoice('A', { picks: [b1.id, b2.id, hg.id] }), false, 'Rip: not two of the same power');
      return { picks: [b1.id, hg.id] };
    });
    toMain2();
    t.zone(b1, 'hand', 'Rip: a Bears');
    t.zone(hg, 'hand', 'Rip: and the Giant, of another power');
    t.zone(b2, 'library', 'Rip: not two of the same power');
    t.zone(isl, 'library');
    t.eq(lib.indexOf(fifth) < lib.indexOf(b2), true, 'Rip: the rest on the bottom');
  });
