  test('Commanders: Cass, Hand of Vengeance — an enchanted and equipped creature dies: its Aura back and its Equipment moved onto a target creature', (mk, t) => {
    t.auto('Cass, Hand of Vengeance');
    const M = mk({ library: Array(30).fill('Island') });
    const g = M.g;
    M.toMain('A');
    const cass = M.bf('A', 'Cass, Hand of Vengeance');
    const bear = M.bf('A', 'Grizzly Bears');
    const aura = M.bf('A', 'Holy Strength'), eq = M.bf('A', 'Bonesplitter');
    const loose = M.bf('A', 'Short Sword');
    for (const x of [aura, eq]) { x.attachedTo = bear.id; bear.attachments = (bear.attachments || []).concat(x.id); }
    g.bumpBoard();
    let items = null;
    M.answer('pickTarget', { targets: [{ kind: 'object', id: cass.id }] });
    M.answer('choose', (ch) => { items = ch.items.map(x => x.id); return { picks: items }; });
    M.mana('A', 'BB1');
    M.cast('A', M.hand('A', 'Murder'), { targets: [bear] });
    t.eq(bear.zone, 'graveyard', 'Cass: the Bears died');
    t.ok(items && items.includes(aura.id) && items.includes(eq.id), 'Cass: the Aura and the Equipment offered');
    t.no(items && items.includes(loose.id), 'Cass: not an Equipment that wasn\'t on it');
    t.ok(aura.zone === 'battlefield' && aura.attachedTo === cass.id, 'Cass: Holy Strength back on Cass');
    t.eq(eq.attachedTo, cass.id, 'Cass: Bonesplitter on Cass');
    t.eq(g.powerOf(cass), (parseInt(cass.card.power, 10) || 0) + 1 + 2, 'Cass: +1 and +2');
  });
