  test('Commanders: Kytheon, Hero of Akros — attacking with two others transforms him; Gideon\'s abilities', (mk, t) => {
    t.auto('Kytheon, Hero of Akros // Gideon, Battle-Forged');
    const M = mk({ library: Array(30).fill('Island') });
    const g = M.g;
    const ky = M.bf('A', 'Kytheon, Hero of Akros');
    const b1 = M.bf('A', 'Grizzly Bears');
    M.answer('declareAttackers', () => [{ attackerId: ky.id, defenderId: 'B' }, { attackerId: b1.id, defenderId: 'B' }]);
    M.toMain('A', 'end');
    t.eq(ky.face || 0, 0, 'Kytheon: one other attacker — not transformed');
    const b2 = M.bf('A', 'Grizzly Bears');
    M.nextTurn('A');
    M.answer('declareAttackers', () => [{ attackerId: ky.id, defenderId: 'B' }, { attackerId: b1.id, defenderId: 'B' }, { attackerId: b2.id, defenderId: 'B' }]);
    M.toMain('A', 'end');
    t.eq(ky.zone, 'battlefield', 'Kytheon: back on the battlefield');
    t.eq(ky.face, 1, 'Kytheon: transformed into Gideon, Battle-Forged');
    t.ok((ky.analysis() || {}).isPlaneswalker, 'Kytheon: a planeswalker');
    t.eq(ky.counters.loyalty, 3, 'Gideon: 3 loyalty');
    // +2: B's creature must attack Gideon on B's next turn
    const foe = M.bf('B', 'Grizzly Bears');
    M.nextTurn('A');
    M.answer('pickTarget', { targets: [{ kind: 'object', id: foe.id }] });
    M.activate('A', ky, 0);
    t.eq(ky.counters.loyalty, 5, 'Gideon: +2');
    M.nextTurn('B');
    let refused = null;
    M.answer('declareAttackers', (ch, gg) => { refused = gg.declareAttackers('B', [{ attackerId: foe.id, defenderId: 'A' }]); return [{ attackerId: foe.id, defenderId: ky.id }]; });
    M.toMain('B', 'declareBlockers');
    t.no(refused, 'Gideon: attacking A instead is refused');
    t.eq(foe.attacking, ky.id, 'Gideon: it attacks Gideon');
    M.nextTurn('B');
    t.no(g.mustAttack(foe), 'Gideon: only during that one turn');
  });
