  test('Commanders: Baron Helmut Zemo — connives on a black spell from hand; boast: exile black cards with fifteen {B}, cast up to three copies free', (mk, t) => {
    t.auto('Baron Helmut Zemo');
    const M = mk({ library: Array(30).fill('Swamp') });
    const g = M.g;
    M.toMain('A');
    const ze = M.bf('A', 'Baron Helmut Zemo');
    // a black spell from hand: Zemo connives (draws, then discards)
    const h0 = M.zone('A', 'hand').length;
    M.mana('A', 'B');
    M.cast('A', M.hand('A', 'Duress'), { targets: ['B'] });
    M.resolve();
    t.eq(M.zone('A', 'hand').length, h0, 'Zemo: connived — a card drawn and one discarded');
    const n0 = g.log.length;
    M.mana('A', 'R');
    M.cast('A', M.hand('A', 'Shock'), { targets: ['B'] });
    t.no(g.log.slice(n0).some(l => /connive/i.test(l.text)), 'Zemo: not for a red spell');
    // boast: only after attacking
    const ob = [1, 2, 3].map(() => M.grave('A', 'Phyrexian Obliterator'));
    const mu = M.grave('A', 'Murder');
    const du = M.grave('A', 'Duress');
    const sh = M.grave('A', 'Lightning Bolt');
    t.no(g.activateAbility('A', ze.id, 0, { auto: true, targets: [] }), 'Zemo: no boast before attacking');
    M.answer('declareAttackers', () => [{ attackerId: ze.id, defenderId: 'B' }]);
    M.toMain('A', 'end');
    const bear = M.bf('B', 'Grizzly Bears');
    let q = null;
    M.answer('choose', (ch) => { q = ch; return { picks: [ob[0].id, mu.id] }; });
    M.answer('pickTarget', { targets: [{ kind: 'object', id: bear.id }] });
    t.ok(g.activateAbility('A', ze.id, 0, { auto: true, targets: [], evidenceIds: ob.concat([mu, du]).map(c => c.id) }), g.lastError);
    M.resolve();
    t.ok(ob.concat([mu, du]).every(c => c.zone === 'exile'), 'Zemo: the five exiled (4+4+4+2+1 = 15 {B})');
    t.eq(sh.zone, 'graveyard', 'Zemo: not the red card');
    t.ok(q && q.max === 3 && q.items.length === 5, 'Zemo: up to three of the five');
    t.eq(bear.zone, 'graveyard', 'Zemo: the Murder copy killed the Bears');
    const tok = M.bfOf('A').filter(o => o.name === 'Phyrexian Obliterator');
    t.ok(tok.length === 1 && tok[0].isToken, 'Zemo: an Obliterator copy, a token');
    t.eq(ob[0].zone, 'exile', 'Zemo: the cards stay exiled');
  });
