    t.ok(ex && ex.candidates.length === 3 && !ex.candidates.includes(isl.id), 'the three creature cards offered, not the Island');
    t.ok(/^Exile any number of creature cards/.test(ex.label), 'as an exile: ' + ex.label);
    T.mana('A', 'BB2');
    T.cast('A', gx, { sacrificeIds: [bears.id, giant.id] });
    t.zone(gx, 'battlefield', 'cast for {2}{B}{B}');
    t.zone(bears, 'exile', 'the Bears exiled'); t.zone(giant, 'exile', 'the Giant exiled');
    t.zone(elves, 'graveyard', 'the Elves kept');
    t.eq(bears.exiledWithId, gx.id, 'exiled with Gorex');
    T.answer('declareAttackers', () => [{ attackerId: gx.id, defenderId: 'B' }]);
    T.nextTurn('A');
    T.toMain('A', 'declareBlockers');
    T.resolve();
    const back = [bears, giant].filter(c => c.zone === 'hand');
    t.eq(back.length, 1, 'attacks: one of them to hand');
    g.moveObject(gx, 'graveyard');
    T.resolve();
    t.ok(bears.zone === 'hand' && giant.zone === 'hand', 'dies: the other to hand');
