    t.eq(g.powerOf(bear) + '/' + g.toughnessOf(bear), '3/4', 'the Bears +1/+2');
    t.no((home.attachments || []).length, 'not on a creature that did not attack');
    t.ok(lands.every(l => l.tapped), '{2} paid');
