    T.answer('pickTarget', { targets: [{ kind: 'object', id: giant.id }] });
    T.nextTurn('A');
    T.answer('declareAttackers', () => [{ attackerId: ak.id, defenderId: 'B' }]);
    T.toMain('A', 'declareBlockers');
