  test("Commanders: Vislor Turlough — enters: an opponent may be given it, goaded while they control it; end step: draw, lose life for the hand", (mk, t) => {
    t.auto('Vislor Turlough');
    const M = mk({ players: ['A', 'B', 'C'], library: Array(30).fill('Swamp') });
    const g = M.g;
    M.nextTurn('A');
    let q = null;
    M.answer('choose', (ch) => { q = ch; return { picks: ['C'] }; });
    const vt = M.hand('A', 'Vislor Turlough');
    M.mana('A', 'B3');
    M.cast('A', vt);
    M.resolve();
    t.ok(q && q.kind === 'players' && q.optional, 'which opponent, or none');
    t.eq(M.asked.filter(x => x.type === 'confirm').length, 0, 'no separate yes/no');
    t.eq(vt.controller, 'C', 'C gains control');
    t.ok(g._goaders(vt).includes('A'), 'goaded by A');
    // C's end step: C draws, then loses life equal to C's hand
    M.nextTurn('C');
    const hc = M.zone('C', 'hand').length;
    const life0 = M.life('C');
    M.answer('declareAttackers', () => [{ attackerId: vt.id, defenderId: 'B' }]);
    M.toMain('C', 'end');
    M.resolve();
    t.eq(M.zone('C', 'hand').length, hc + 1, 'C draws at its end step');
    t.eq(M.life('C'), life0 - (hc + 1), 'and loses life equal to its hand');
    t.eq(M.life('B'), 20 - g.powerOf(vt), 'goaded, it attacked B');
    // control back to A: no longer goaded
    vt.effects.push({ control: 'A', until: null, ts: g._stampNew() });
    g._refreshControl();
    t.eq(vt.controller, 'A', 'A has it back');
    t.no(g._goaders(vt).includes('A'), 'no longer goaded');
    // two players: one yes/no question; declined, kept
    const T2 = mk({ library: Array(30).fill('Swamp') });
    T2.nextTurn('A');
    T2.answer('confirm', { yes: false });
    const v2 = T2.hand('A', 'Vislor Turlough');
    T2.mana('A', 'B3');
    T2.cast('A', v2);
    T2.resolve();
    const c2 = T2.asked.filter(x => x.type === 'confirm');
    t.eq(c2.length, 1, 'one question');
    t.ok(/Have B gain control of Vislor Turlough\? It's goaded for as long as they control it\./.test(c2[0].prompt), 'the question: ' + c2[0].prompt);
    t.eq(v2.controller, 'A', 'declined: kept');
  });
