  test('Commanders: Bohn, Beguiling Balladeer — every nonland card in hand has foretell for its mana cost less {2}', (mk, t) => {
    t.auto('Bohn, Beguiling Balladeer');
    const T = mk({ library: Array(20).fill('Forest') });
    const g = T.g;
    const bohn = T.bf('A', 'Bohn, Beguiling Balladeer');
    const bears = T.hand('A', 'Grizzly Bears'), saw = T.hand('A', 'Saw It Coming'), land = T.hand('A', 'Forest');
    const fu = (o) => g.altUsesFor('A', o.id).find(u => u.kind === 'foretell');
    t.ok(fu(bears) && fu(bears).cost === '{2}', 'the Bears: foretell for {2}');
    t.no(fu(land), 'not a land');
    t.eq(g.altUsesFor('A', saw.id).filter(u => u.kind === 'foretell').length, 1, 'a card with its own foretell: that one only');
    T.mana('A', 'G1');
    t.ok(g.foretellCard('A', bears.id, { auto: true }), 'foretold');
    t.zone(bears, 'exile', 'exiled');
    t.ok(bears.faceDownExile, 'face down');
    t.no(JSON.stringify(g.viewFor('B')).includes('Grizzly Bears'), 'the opponent does not see it');
    t.ok(JSON.stringify(g.viewFor('A')).includes('Grizzly Bears'), 'its owner does');
    t.no(g.altUsesFor('A', bears.id).some(u => u.via === 'foretell'), 'not castable the turn it was foretold');
    T.mana('A', 'UU');
    t.ok(g.foretellCard('A', saw.id, { auto: true }), 'Saw It Coming foretold');
    T.nextTurn('B'); T.toMain('B');
    const b2 = T.hand('A', 'Hill Giant');
    t.no(fu(b2), "not during an opponent's turn");
    g.moveObject(bohn, 'graveyard');
    T.nextTurn('A'); T.toMain('A');
    const cu = g.altUsesFor('A', bears.id).find(u => u.via === 'foretell');
    t.ok(cu && cu.cost === '{G}', 'Bohn gone: still castable, for {G}: ' + (cu && cu.cost));
    t.eq((g.altUsesFor('A', saw.id).find(u => u.via === 'foretell') || {}).cost, '{1}{U}', "Saw It Coming: its own foretell cost");
    T.mana('A', 'G');
    T.cast('A', bears, { via: 'foretell' });
    t.zone(bears, 'battlefield', 'cast from exile for {G}');
    t.no(bears.faceDownExile || bears.foretold, 'face up, foretold no more');
  });
