  test("Commanders: Will Kenrith — +2: up to two creatures 0/3 with no abilities until your next turn; −2: that player draws two, their instants cost {2} less until your next turn", (mk, t) => {
    t.auto('Will Kenrith');
    const T = mk({ library: Array(20).fill('Island') });
    const g = T.g;
    const will = T.bf('A', 'Will Kenrith');
    const drake = T.bf('B', 'Wind Drake'), giant = T.bf('B', 'Hill Giant');
    T.activate('A', will, 0, { targets: [drake, giant] });
    t.eq(will.counters.loyalty, 6, '+2');
    t.eq(g.powerOf(giant) + '/' + g.toughnessOf(giant), '0/3', 'Hill Giant 0/3');
    t.eq(g.powerOf(drake) + '/' + g.toughnessOf(drake), '0/3', 'Wind Drake 0/3');
    t.no(g.hasKw(drake, 'flying'), 'no flying');
    T.nextTurn('B');
    t.eq(g.powerOf(giant), 0, "still on B's turn");
    T.nextTurn('A');
    t.eq(g.powerOf(giant) + '/' + g.toughnessOf(giant), '3/3', 'your next turn: over');
    t.ok(g.hasKw(drake, 'flying'), 'flying back');
    // −2 on B: B draws two; B's instants cost {2} less through B's turn, until A's next turn
    const h0 = T.zone('B', 'hand').length, a0 = T.zone('A', 'hand').length;
    T.activate('A', will, 1, { targets: ['B'] });
    t.eq(T.zone('B', 'hand').length, h0 + 2, 'B drew two');
    t.eq(T.zone('A', 'hand').length, a0, 'A drew none');
    T.mana('A', 'U');
    t.no(g.castSpell('A', T.hand('A', 'Divination').id, { auto: true, targets: [] }), 'not cheaper for A');
    T.nextTurn('B');
    T.mana('B', 'U');
    T.cast('B', T.hand('B', 'Divination'));
    t.eq(T.zone('B', 'hand').length, h0 + 2 + 1 + 2, "B's turn: Divination for {U}");
    T.mana('B', 'G');
    t.no(g.castSpell('B', T.hand('B', 'Grizzly Bears').id, { auto: true, targets: [] }), 'a creature: full price');
    const T2 = mk({ library: Array(20).fill('Island') });
    const w2 = T2.bf('A', 'Will Kenrith');
    T2.activate('A', w2, 1, { targets: ['B'] });
    T2.nextTurn('B'); T2.nextTurn('A');
    T2.mana('B', 'U');
    t.no(T2.g.castSpell('B', T2.hand('B', 'Divination').id, { auto: true, targets: [] }), "A's next turn: over");
  });
